    sd_corners_d: { en:"Corner scale for cards, lists, menus, Settings and toasts.", es:"Escala de las esquinas de tarjetas, listas, menús, Ajustes y avisos.", zh:"卡片、列表、菜单、设置和提示的圆角比例。", hi:"कार्ड, सूची, मेनू, सेटिंग्स और टोस्ट के कोनों का स्केल।", pt:"Escala dos cantos de cartões, listas, menus, Configurações e avisos.", fr:"Échelle des coins des cartes, listes, menus, Paramètres et toasts.", de:"Eckenskala für Karten, Listen, Menüs, Einstellungen und Toasts.", ja:"カード、リスト、メニュー、設定、トーストの角のスケール。", ru:"Масштаб углов карточек, списков, меню, настроек и всплывающих сообщений." },
    sd_card: { en:"Card", es:"Tarjeta", zh:"卡片", hi:"कार्ड", pt:"Cartão", fr:"Carte", de:"Karte", ja:"カード", ru:"Карточка" },
    sd_card_d: { en:"The radius grows on hover and the card shrinks a little when pressed.", es:"El radio crece al pasar el cursor y la tarjeta se comprime un poco al presionar.", zh:"悬停时圆角变大，按下时卡片稍微缩小。", hi:"होवर पर रेडियस बढ़ता है और दबाने पर कार्ड थोड़ा सिकुड़ता है।", pt:"O raio aumenta ao passar o cursor e o cartão encolhe um pouco ao pressionar.", fr:"Le rayon augmente au survol et la carte rétrécit légèrement à l'appui.", de:"Der Radius wächst beim Überfahren und die Karte schrumpft beim Drücken etwas.", ja:"ホバーで角丸が大きくなり、押すとカードが少し縮みます。", ru:"Радиус растёт при наведении, а карточка слегка сжимается при нажатии." },
    sd_list_d: { en:"Segmented list", es:"Lista segmentada", zh:"分段列表", hi:"खंडित सूची", pt:"Lista segmentada", fr:"Liste segmentée", de:"Segmentierte Liste", ja:"セグメントリスト", ru:"Сегментированный список" },
    sd_physics: { en:"Spring physics", es:"Física de resortes", zh:"弹簧物理", hi:"स्प्रिंग भौतिकी", pt:"Física de molas", fr:"Physique des ressorts", de:"Federphysik", ja:"スプリング物理", ru:"Физика пружин" },
    sd_physics_d: { en:"Motion is defined by stiffness and damping instead of duration + curve. Spatial springs may bounce; effects never do.", es:"El movimiento se define con rigidez y amortiguamiento en vez de duración + curva. Los resortes espaciales pueden rebotar; los de efectos nunca.", zh:"动效由刚度和阻尼定义，而不是时长 + 曲线。空间弹簧可能回弹；效果弹簧永远不会。", hi:"मोशन अवधि + कर्व के बजाय कठोरता और डैम्पिंग से तय होता है। स्पेशियल स्प्रिंग उछल सकते हैं; इफ़ेक्ट कभी नहीं।", pt:"O movimento é definido por rigidez e amortecimento em vez de duração + curva. As molas espaciais podem quicar; as de efeitos nunca.", fr:"Le mouvement est défini par la raideur et l'amortissement plutôt que durée + courbe. Les ressorts spatiaux peuvent rebondir ; les effets jamais.", de:"Bewegung wird durch Steifigkeit und Dämpfung statt Dauer + Kurve definiert. Räumliche Federn können nachschwingen, Effekte nie.", ja:"モーションは時間＋カーブではなく、剛性と減衰で定義されます。空間スプリングは弾むことがありますが、エフェクトは弾みません。", ru:"Анимация задаётся жёсткостью и затуханием, а не длительностью + кривой. Пространственные пружины могут пружинить; эффекты — никогда." },
    sd_speed: { en:"Speed", es:"Velocidad", zh:"速度", hi:"गति", pt:"Velocidade", fr:"Vitesse", de:"Geschwindigkeit", ja:"速度", ru:"Скорость" },
